Happy-path test (observed):
  cmd: printf 'SAVED_CONTENT' | pbcopy
  cmd: agent-desktop type @e2 "café" --snapshot s32r1740c1pwh3 --headed
  result: {"command":"type","data":{"post_state":{"role":"textfield","value":"café"}},"ok":true}
